SELECT instance_name, host_name, status, database_status,
       TO_CHAR(startup_time,'DD/MM/YYYY HH24:MI:SS') AS startup,
       logins
FROM v$instance;

SELECT name, open_mode, database_role FROM v$database;

SELECT name, network_name, creation_date, pdb
FROM v$services ORDER BY name;

SELECT value AS service_names FROM v$parameter WHERE name='service_names';
SELECT value AS local_listener  FROM v$parameter WHERE name='local_listener';
